int list_item_to_string(node *head, char *str) {
    int quantity = 0;
    int i = 0;

    // count the quantity of items in the list
    node *current = head;
    while (current!= NULL) {
        quantity++;
        current = current->next;
    }

    // calculate the total length of the output string
    int len = snprintf(NULL, 0, "%d x %s @ $%.2f price ea", quantity, head->item_name, head->price);

    // copy the quantity into the output string
    snprintf(str, MAX_ITEM_PRINT_LEN, "%d x ", quantity);

    // copy the item name into the output string
    snprint(str + strlen(str), MAX_ITEM_PRINT_LEN - strlen(str), "%s", head->item_name);

    // copy the price into the output string
    snprint(str + strlen(str), MAX_ITEM_PRINT_LEN - strlen(str), " @ $%.2f", head->price);

    // add the "price ea" to the end of the output string
    snprint(str + strlen(str), MAX_ITEM_PRINT_LEN - strlen(str), " price ea");

    return 0;
}
