    if (head == NULL) {
        sprintf(buffer, "0 x None @ $0.00");
        length = strlen(buffer);
    } else {
        sprintf(buffer, "%d x %s @ $%.2f", head->quantity, head->item_name, head->price);
        length = strlen(buffer);
    }

    strncpy(str, buffer, MAX_ITEM_PRINT_LEN - 1);
    str[MAX_ITEM_PRINT_LEN - 1] = '\0'; // ensure str is null-terminated

    return length;
}
