    // Check if buffer is NULL to prevent buffer overflow
    if (buffer == NULL) {
        buffer = malloc(BUFFER_SIZE);
        if (buffer == NULL) {
            // Handle memory allocation failure
            printf("Error: Unable to allocate memory for buffer.\n");
            exit(EXIT_FAILURE);
        }
    }

    // Calculate the length of the message, including the null terminator
    size_t message_length = strlen(message);

    // Copy the message into the buffer, leaving room for the null terminator
    if (message_length < BUFFER_SIZE - 1) {
        strncpy(buffer, message, BUFFER_SIZE - 1);
    } else {
        // Handle buffer overflow
        buffer[BUFFER_SIZE - 1] = '\0';
        buffer[BUFFER_SIZE] = '\0';
    }

    buffer[BUFFER_SIZE - 1] = '\0';  // Ensure null termination

    // Return the buffer (not necessary in this case, but added for completeness)
    buffer;
}
