int list_load(node **head, char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) return -1;

    char line[MAX_LINE_LEN];
    node *cur = NULL;

    while (fgets(line, MAX_LINE_LEN, fp)) {
        line[strcspn(line, "\n")] = 0; // remove newline character
        node *new_node = malloc(sizeof(node));
        if (!new_node) return -1;

        new_node->item_name = strdup(line);
        if (!new_node->item_name) return -1;

        new_node->price = atof(line);
        new_node->quantity = atoi(line + strlen(line) - strlen(line) + 7);
        line[strlen(line) - 7] = '\0'; // reset line for next iteration

        if (!*head) {
            *head = new_node;
            cur = new_node;
        } else {
            cur->next = new_node;
            cur = new_node;
        }
    }

    fclose(fp);
    return 0;
}
