    int num_fields = 0;
    char *ptr = strtok(line, ",");
    while (ptr!= NULL && num_fields < max_fields) {
        if (num_fields > 0) {
            ptr = NULL;
            ptr = strtok(NULL, ",");
        }
        if (ptr!= NULL) {
            if (num_fields < max_fields) {
                strncpy(fields[num_fields], ptr, MAX_FIELD_LEN - 1);
                fields[num_fields][MAX_FIELD_LEN - 1] = '\0';
