int parse_csv_line(const char *line, char fields[][MAX_FIELD_LEN], int max_fields) {
    int num_fields = 0;
    int start_pos = 0;
    int len;

    while (num_fields < max_fields - 1 && start_pos < strlen(line)) {
        len = strcspn(line + start_pos, ",");
        fields[num_fields][len] = '\0';
        if (len > MAX_FIELD_LEN) {
            fprintf(stderr, "Error: Field exceeds maximum length\n");
            return num_fields;
        }
        num_fields++;
        start_pos += len + 1;
    }

    if (start_pos < strlen(line)) {
        len = strlen(line + start_pos);
        if (len > MAX_FIELD_LEN) {
            fprintf(stderr, "Error: Field exceeds maximum length\n");
