    if (logfile == NULL || status == NULL) {
        fprintf(stderr, "Error: Invalid log file or status message\n");
        return;
    }

    if (flock(logfile, LOCK_EX) == -1) {
        fprintf(stderr, "Error: Unable to lock log file for writing\n");
        return;
    }

    fprintf(logfile, "%s\n", status);
    fflush(logfile);

    if (flock(logfile, LOCK_UN) == -1) {
        fprintf(stderr, "Error: Unable to unlock log file\n");
    }
}
