void write_log(FILE *logfile, const char *status) {
    char date[20];
    char time[20];
    time_t rawtime;
    struct tm *lt;

    time(&rawtime);
    lt = localtime(&rawtime);
    strftime(date, sizeof(date), "%Y-%m-%d", lt);
    strftime(time, sizeof(time), "%H:%M:%S", lt);

    fprintf(logfile, "[%s %s] %s\n", date, time, status);

    fflush(logfile);
}
