void write_log(FILE *logfile, const char *status) {
    if (logfile == NULL || status == NULL) {
        fprintf(stderr, "Error: Invalid log file or status message.\n");
        return;
    }

    if (flock(fileno(logfile), LOCK_EX)!= 0) {
        fprintf(stderr, "Error: Unable to lock log file.\n");
        return;
    }

    fprintf(logfile, "%s - %s\n", asctime(localtime(&time(NULL))), status);

    if (fflush(logfile)!= 0) {
        fprintf(stderr, "Error: Unable to flush log file.\n");
    }

    if (flock(fileno(logfile), LOCK_UN)!= 0) {
        fprintf(stderr, "Error: Unable to unlock log file.\n");
    }
}
```

