// Helper function to get the current date and time
char *get_current_datetime() {
    static char date[20];
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(date, sizeof(date), "%Y-%m-%d %H:%M:%S", timeinfo);
    return date;
}

void write_log(FILE *logfile, const char *status) {
    if (logfile!= NULL && status!= NULL) {
        fprintf(logfile, "%s - %s\n", get_current_date(), status);
        fflush(logfile);
    } else {
        fprintf(stderr, "Error: Invalid log file or status message\n");
    }
}

// Helper function to get the current date in the format "YYYY-MM-DD HH:MM:SS"
char *get_current_date() {
    static char date[20];
    struct tm *current_date;
    current_date = localtm(localtime_r(NULL, &current_date));
    strftime(date, sizeof(date), "%Y-%m-%d %H:%M:%S", current_date);
    return date;
}

